"""Fresh-account, source-first usability regression; every mutation reaches real HTTP + SQLite."""
from bridge import Bridge,ROOT
from playwright.sync_api import sync_playwright,expect
from pathlib import Path
import os,json,secrets,uuid
out=Path(os.environ.get('THREADLINE_FOCUS_OUTPUT',ROOT/'artifacts/v1.2/focus-browser'));out.mkdir(parents=True,exist_ok=True)
checks=[];errors=[]
def mark(name):
 checks.append({'check':name,'status':'passed'});print('PASS',name,flush=True)
def fit(page,name):
 assert page.evaluate('document.documentElement.scrollWidth <= innerWidth+1'),name
 mark(name+' fits viewport')
def route(page,path):
 page.evaluate('(p)=>location.hash="#"+p',path);page.wait_for_timeout(350)
def screenshot(page,name):
 page.wait_for_timeout(350);page.screenshot(path=str(out/(name+'.png')),full_page=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.environ.get('THREADLINE_BROWSER_PATH','/usr/bin/chromium'),headless=True)
 context=browser.new_context(viewport={'width':1440,'height':1000},device_scale_factor=1)
 page=context.new_page();page.set_default_timeout(9000);page.on('pageerror',lambda e:errors.append(str(e)))
 bridge=Bridge();password='Test-only-'+secrets.token_hex(12);email='focus-'+str(uuid.uuid4())[:8]+'@example.invalid'
 try:
  bridge.mount(page);page.wait_for_selector('#auth-form')
  page.locator('#f-name').fill('Alex Rivera');page.locator('#f-email').fill(email);page.locator('#f-password').fill(password);page.locator('#f-inviteCode').fill(os.environ['THREADLINE_TEST_INVITATION'])
  page.get_by_role('button',name='Create private workspace').click();page.wait_for_selector('.focus-hero')
  assert len(bridge.json('/api/state')['contacts'])==0;mark('Create a genuinely empty account through the interface');screenshot(page,'01_empty_home');fit(page,'Empty Today')
  page.get_by_role('button',name='Save your first conversation').click();page.wait_for_selector('#capture-form');screenshot(page,'02_capture_empty')
  body='Maya worked on robotics supply chains. She offered to review a short project outline, subject to availability. I promised to send a relevant case study.'
  page.locator('#capture-body').fill(body);page.locator('#f-contact_id').select_option('__new__');page.locator('#f-person_name').fill('Maya Chen');page.locator('#f-person_company').fill('Ridgeway Robotics');page.locator('#f-person_role').fill('Operations lead');page.locator('#f-channel').select_option('wechat');page.locator('#f-occurred_on').fill('2026-10-16')
  page.get_by_text('Keep a promise',exact=False).first.click();page.locator('#f-reminder_title').fill('Send Maya the relevant case study');page.locator('#f-reminder_due').fill('2026-11-01');fit(page,'Capture');screenshot(page,'03_capture_filled')
  page.get_by_role('button',name='Save conversation',exact=True).click();page.wait_for_selector('.saved-scene');mark('Save a conversation, a new person and a reminder without a project')
  st=bridge.json('/api/state');assert len(st['projects'])==0 and len(st['notes'])==1 and len(st['tasks'])==1;assert st['notes'][0]['excerpt'] in body;person=st['contacts'][0];note=st['notes'][0]
  screenshot(page,'04_saved');mark('Fresh source is persisted and acknowledged rather than simulated')
  route(page,'discover');page.locator('#find-query').fill('robotics supply chains');page.locator('#find-query').press('Enter');page.wait_for_selector('.person-result');expect(page.locator('.person-result')).to_contain_text('Maya Chen');expect(page.locator('.person-result')).to_contain_text(body);mark('Topic search retrieves the real person with exact original context')
  fit(page,'Find people');screenshot(page,'05_find_people')
  page.locator('[data-action=useful-find]').first.click();page.wait_for_timeout(250);assert bridge.json('/api/week')['useful_finds']==1;mark('Usefulness feedback is a real account event, not an outreach metric')
  page.get_by_role('link',name='Open brief',exact=False).first.click();page.wait_for_selector('.brief-timeline');expect(page.locator('.brief-timeline')).to_contain_text(body);screenshot(page,'06_brief');fit(page,'Relationship brief');mark('The briefing connects the person, original source and open reminder')
  task=st['tasks'][0];cal=bridge.json('/api/tasks/'+task['id']+'/calendar');assert 'DTSTART;VALUE=DATE:20261101' in cal['content'];mark('Calendar content is generated by the authorized real endpoint')
  page.locator('[data-action=toggle-task]').first.click();page.wait_for_timeout(300);assert bridge.json('/api/state')['tasks'][0]['status']=='done';mark('Complete the persisted reminder from the relationship brief')
  route(page,'week');page.wait_for_selector('.week-metrics');assert bridge.json('/api/week')['completed_commitments']==1;screenshot(page,'07_week');fit(page,'This week');mark('Weekly review reflects source capture, explicit feedback and completed work')
  route(page,'connect');screenshot(page,'08_connect');fit(page,'Bring context');assert 'No login sharing' in page.locator('#main').inner_text();mark('Integration screen states what is manual and what is a one-time export')
  route(page,'discover/quantum-entanglement');assert 'Maya Chen' not in page.locator('#main').inner_text();screenshot(page,'09_no_results');mark('A missing topic does not fabricate a person or evidence')
  route(page,'capture');page.locator('#capture-body').fill('Unsaved private draft');route(page,'overview');route(page,'capture');expect(page.locator('#capture-body')).to_have_value('Unsaved private draft');mark('An unsaved capture survives in-page navigation, not server submission')
  # Expired session response clears both private application state and the in-memory capture draft.
  bridge.json('/api/auth/logout','POST',{},bridge.json('/api/auth/status')['csrf']);route(page,'week');page.wait_for_selector('#auth-form');assert page.locator('#capture-form').count()==0;mark('Session expiry removes stale private forms before the next login')
  page.locator('#f-email').fill(email);page.locator('#f-password').fill(password);page.get_by_role('button',name='Sign in',exact=False).click();page.wait_for_selector('.focus-hero');route(page,'capture');expect(page.locator('#capture-body')).to_have_value('');mark('Signing back in does not reveal an expired capture draft')
  page.set_viewport_size({'width':390,'height':844})
  for view in ['overview','capture','discover/robotics','person/'+person['id'],'week','connect']:
   route(page,view);fit(page,'Mobile '+view.split('/')[0]);screenshot(page,'mobile_'+view.split('/')[0])
   page.get_by_role('button',name='Toggle navigation',exact=True).click();expect(page.locator('[data-nav=capture]')).to_be_visible();page.get_by_role('button',name='Close navigation',exact=True).click()
  mark('Mobile navigation can be opened and closed on all new screens')
  page.set_viewport_size({'width':1440,'height':1000});route(page,'note/'+note['id']);page.wait_for_selector('#note-body')
  auth=bridge.json('/api/auth/status');bridge.json('/api/notes/'+note['id'],'DELETE',{'version':note['version']},auth['csrf']);route(page,'discover/supply');assert 'Maya Chen' not in page.locator('#main').inner_text();mark('Source deletion removes old context from new discovery results')
  route(page,'person/'+person['id']);expect(page.locator('.brief-timeline')).not_to_contain_text(body);mark('The brief does not retain withdrawn source text')
  # Simulate the extension's selected-text handoff, not a native extension installation.
  from urllib.parse import urlencode
  selected='A new selected browser passage about accessible onboarding.'
  before=len(bridge.json('/api/state')['notes'])
  incoming=context.new_page();incoming.on('pageerror',lambda e:errors.append(str(e)))
  bridge.mount(incoming,'#capture?'+urlencode({'text':selected,'title':'Selected browser passage','url':'https://example.invalid/article?tracking=1#part'}))
  incoming.wait_for_selector('#capture-form');expect(incoming.locator('#capture-body')).to_have_value(selected)
  assert 'text=' not in incoming.evaluate('location.hash');mark('Selected-text handoff prefills an unsaved draft and scrubs the private URL fragment')
  assert len(bridge.json('/api/state')['notes'])==before;mark('Opening a selection never auto-saves or calls an external provider')
  incoming.get_by_role('button',name='Save conversation',exact=True).click();incoming.wait_for_selector('.saved-scene')
  assert len(bridge.json('/api/state')['notes'])==before+1;mark('The imported selection is persisted only after explicit Save')
  incoming.close()
  page.set_viewport_size({'width':390,'height':844});route(page,'overview');page.get_by_role('button',name='Toggle navigation',exact=True).click();page.keyboard.press('Escape')
  expect(page.get_by_role('button',name='Toggle navigation',exact=True)).to_have_attribute('aria-expanded','false');mark('Escape closes mobile navigation and restores its expanded state')
  assert not errors,errors;mark('No JavaScript errors across first-use and mobile workflows')

 except Exception:
  screenshot(page,'FAILURE');raise
 finally:
  browser.close()
report={'release':'1.3.1','status':'passed','transport':os.environ.get('THREADLINE_BROWSER_MODE','native'),'scope':'Actual shipped HTML/CSS/JS, real authenticated localhost HTTP/SQLite. Renderer mode does not exercise native navigation/CSP/cookies, downloads or extension installation.','checks':checks,'errors':errors}
assert not errors,errors
(out/'report.json').write_text(json.dumps(report,indent=2));print(json.dumps({'passed':len(checks),'errors':errors}))
